  %
  Let $\pi \in S_n$ be such that $\pi(i) = n$ for some $i < n$. Then $\pi(\pi(i)) < n$.
\end{proposition}

n16140.content:
\begin{proof}
  \leanok
  Assume, for a contradiction, that $\pi(\pi(i)) \geq n$. Then
  \begin{equation*}
    \pi(\pi(i)) = n = \pi(i) \implies \pi(i) = i \implies i = n < n,
  \end{equation*}
  which is a contradiction.
\end{proof}

